import { mkdtemp, readFile, rm, writeFile } from 'node:fs/promises';
import { spawnSync } from 'node:child_process';
import { join } from 'node:path';
import { tmpdir } from 'node:os';
import { PrismaClient } from '@prisma/client';

// Setting used to be keyed by `key String @id` alone. #1553/#2249 replaced that
// with a surrogate `id String @id @default(cuid())` plus `@@unique([orgId, key])`
// so a row can be scoped per tenant. `id`'s default is generated by the Prisma
// Client, not the database, so `db push` refuses to add it as a NOT NULL column
// to a populated table outright ("There are N rows in this table, it is not
// possible to execute this step") — `--accept-data-loss` does not override this,
// because it is not a data-loss warning, it is "this step cannot produce a
// value". Converge to an expand schema that keeps `key` as the primary key (its
// live, unchanged shape) and adds `id` as a plain nullable column; the normal
// db push can then backfill it (see prisma/backfill-setting-id.mjs) and contract
// to the final schema, where `id` is the primary key and `key` is not.
//
// `@@unique([orgId, key])` cannot come along for this phase: `orgId` is
// optional, and Prisma requires a model's unique criteria to consist only of
// required fields ("Each model must have at least one unique criteria that has
// only required fields") — `key` alone, still `@id`, satisfies that instead.
const sourcePath = 'prisma/schema.prisma';
const finalBlock =
  'model Setting {\n' +
  '  id        String   @id @default(cuid())\n' +
  '  orgId     String?\n' +
  '  key       String\n' +
  '  value     String   @db.Text\n' +
  '  updatedAt DateTime @updatedAt\n' +
  '\n' +
  '  org Organization? @relation(fields: [orgId], references: [id], onDelete: Cascade)\n' +
  '\n' +
  '  @@unique([orgId, key])\n' +
  '}\n';
const expandBlock =
  'model Setting {\n' +
  '  id        String?\n' +
  '  orgId     String?\n' +
  '  key       String   @id\n' +
  '  value     String   @db.Text\n' +
  '  updatedAt DateTime @updatedAt\n' +
  '\n' +
  '  org Organization? @relation(fields: [orgId], references: [id], onDelete: Cascade)\n' +
  '}\n';
const tempDirectory = await mkdtemp(join(tmpdir(), 'setting-id-expand-'));
const expandPath = join(tempDirectory, 'schema.prisma');

try {
  const schema = await readFile(sourcePath, 'utf8');
  if (!schema.includes(finalBlock)) {
    throw new Error('Setting.id marker not found; expand push not attempted');
  }

  // The unique directory is mode 0700 on supported platforms; explicitly keep
  // the generated schema owner-readable/writable only as an additional guard.
  await writeFile(expandPath, schema.replace(finalBlock, expandBlock), {
    encoding: 'utf8',
    mode: 0o600,
    flag: 'wx',
  });

  if (process.argv.includes('--validate-only')) {
    const validation = spawnSync('npx', ['prisma', 'validate', '--schema', expandPath], {
      stdio: 'inherit',
      env: process.env,
    });
    if (validation.error) throw validation.error;
    process.exitCode = validation.status ?? 1;
  } else {
    // One-shot: once every row has an `id`, the final contract push no longer
    // needs this step, and re-running it against the final schema (where `id`
    // is already required) would just be a no-op push of an unreachable schema.
    const prisma = new PrismaClient();
    try {
      const settingTable = await prisma.$queryRaw`
        SELECT 1
        FROM information_schema.tables
        WHERE table_schema = DATABASE()
          AND table_name = 'Setting'
        LIMIT 1
      `;
      const idColumn = await prisma.$queryRaw`
        SELECT IS_NULLABLE
        FROM information_schema.columns
        WHERE table_schema = DATABASE()
          AND table_name = 'Setting'
          AND column_name = 'id'
        LIMIT 1
      `;

      if (settingTable.length > 0 && idColumn.length > 0 && idColumn[0].IS_NULLABLE === 'NO') {
        console.log('Setting.id is already NOT NULL; expand phase already complete');
      } else {
        const result = spawnSync(
          'npx',
          ['prisma', 'db', 'push', '--schema', expandPath, '--accept-data-loss', '--skip-generate'],
          { stdio: 'inherit', env: process.env },
        );
        if (result.error) throw result.error;
        process.exitCode = result.status ?? 1;
      }
    } finally {
      await prisma.$disconnect();
    }
  }
} finally {
  await rm(tempDirectory, { recursive: true, force: true });
}
